SELECT c.CountryName
FROM countries c
WHERE c.CountryId NOT IN (SELECT Country FROM car_makers);

SELECT p.Name
FROM people p
WHERE p.People_ID NOT IN (SELECT People_ID FROM poker_player);

SELECT DISTINCT cl.CountryCode
FROM countrylanguage cl
WHERE LOWER(cl.Language) != LOWER('English');

SELECT c.Name AS Conductor_Name, o.Orchestra 
FROM conductor c
INNER JOIN orchestra o ON c.Conductor_ID = o.Conductor_ID;

SELECT c.Name AS Conductor_Name, o.Orchestra
FROM conductor c
JOIN orchestra o ON c.Conductor_ID = o.Conductor_ID;

SELECT DISTINCT student_id
FROM Friend
WHERE student_id IN (SELECT liked_id FROM Likes);

SELECT DISTINCT h.name
FROM Highschooler h
WHERE EXISTS (
    SELECT 1 FROM Friend f WHERE f.student_id = h.ID OR f.friend_id = h.ID
)
AND EXISTS (
    SELECT 1 FROM Likes l WHERE l.liked_id = h.ID
);

SELECT DISTINCT o.state
FROM Owners o
INNER JOIN Professionals p ON LOWER(o.state) = LOWER(p.state);
